"""Original i-Mix normal wire facts from intact own-model publisher objects."""
from curated import add, profile

IMIX_ORIGINAL_REFERENCES={"DJ-Tech I-MIX":{'url': 'https://djdecks.be/index.php?module=docs&sub_help=djtech.php', 'sha256': '7a992e3c26dd9e8c7f21c37075c032910c4f36b10ea91bff099a04039c2d5810', 'files': [{'cachePath': 'TestBuilds/r465/upstream/djdecks-dx.exe', 'sha256': '161621012b0b3389cb351d22845441179605171adcb2c16775499ed0344bfb8f'}, {'cachePath': 'TestBuilds/r465/upstream/djdecks-data/devices/djtech_imix.xml', 'sha256': '7a992e3c26dd9e8c7f21c37075c032910c4f36b10ea91bff099a04039c2d5810'}, {'cachePath': 'TestBuilds/r465/upstream/imix-manufacturer-table-web-excerpt.txt', 'sha256': 'df4be0b5d9b3d57e286def4194032632fda213f96fa6c9681807f3bdda303933'}, {'cachePath': 'TestBuilds/r465/upstream/imix-manual-2.jpg', 'sha256': '2686ae44230bfc8f992bfe895c2b34e0ee7c13208ddda5da24150f553a65a360'}, {'cachePath': 'TestBuilds/r465/upstream/imix-manual-3.jpg', 'sha256': '6868333c46938ec6ebb6b9283d8b64ba1ba44a96926028cd0982fde2fa706c71'}, {'cachePath': 'TestBuilds/r465/upstream/imix-manual-4.jpg', 'sha256': 'd9299ea48382e4a94d2c2a21cbfc81a63ad76942d09fb9218edb42ee1b17a739'}, {'cachePath': 'TestBuilds/r465/upstream/imix-manual-5.jpg', 'sha256': '6868333c46938ec6ebb6b9283d8b64ba1ba44a96926028cd0982fde2fa706c71'}], 'relatedSources': [{'url': 'https://djdecks.be/download/djDecksDX.exe', 'sha256': '161621012b0b3389cb351d22845441179605171adcb2c16775499ed0344bfb8f'}, {'url': 'https://djdecks.be/index.php?module=docs&sub_help=midi_xml.php'}, {'url': 'https://manuzoid.com/manuals/KbEr0-DJ-Tech%20i-mix%20club%20edition%20User%20manual'}], 'review': 'Own-model djDecks DX1.02 publisher XML read as data from its public trial archive, without running the installer, mapper or embedded scripts. The file and descriptor identify i-Mix and its MIDI endpoint DJ-Tech i-Mix. The top-level name incorrectly says Kontrol One; it is not used as identity evidence. Own manufacturer combined i-Mix/Club Edition manual supplies the indexed note/CC table and front layouts. The normal publisher controls before the lower-case pitch tabs parse strictly without repair. Four later XML errors at lines627/655/656/695 are in unused jog tabs and are not imported. Every active wire is checked against an intact normal root object: raw0 A/B Play20/55, held native Cue13/48, In1/36, Out8/43, Reloop15/50, bend-/+14/22 and49/29, PFL17/24. Own absolute mixer CCs are A gain72/high69/mid70/low71/level67; B gain75/high76/mid74/low73/level66; global cross65. Both note releases retain native ownership. Four positive-only encoder note wires explicitly scroll the active playlist: Down82/80 and Up83/81, mapped to repeated native track browse pulses. No relative-CC encoder format is guessed. Manual selection only; automatic stored state/discovery and the complete source archive are not qualified. Cue/loop/pitch/jog/FX/software-tab modes, encoder-push keyboard selection, Sync versus one-off MatchBPM/PitchReset, Keylock versus alternate faceplate actions, Hot Cues/modifiers, kill/reset, pitch polarity/range and every output/lamp remain inactive. The source INPUT_OUTPUT tags alone do not qualify native feedback polarity/lifecycle. Source byte types are corroborated by the manufacturer table; the cached table is indexed web text, not a PDF hash, and JPEGs are page backgrounds rather than complete text rendering. Exact USB naming/OS/power/audio/DVS, full lifecycle/recovery and physical/iPad/A10X acceptance remain open. Requires an exposed CoreMIDI source and separate app audio. No firmware, driver, setup, query, preset, keyboard injection, source-mode or audio-route write runs. No Reload/MKII/Kontrol One protocol or software behaviour is inherited.'}}


def imix_original_profiles():
    """Return only the manual, intact normal two-deck core without source scripts."""
    ref=IMIX_ORIGINAL_REFERENCES['DJ-Tech I-MIX']
    p=profile('DJ-Tech I-MIX',ref['url'])
    p.update(autoSelect=False,definition='reviewed:imix-original-intact-normal-core',
        aliases=['DJ-Tech I-MIX','DJ-Tech i-Mix','i-Mix','iMix','DJ-Tech i-Mix Club Edition'],
        excludedAliases=['i-Mix Reload','DJ-Tech i-Mix Reload','I-MIX RELOAD MKII','Kontrol One'],
        hardwareMode='Manual original i-Mix raw0 normal core only, through an already exposed CoreMIDI source. Other software tabs, stored mode/discovery, motion and full USB/OS support remain unqualified. Configure app audio separately.',
        scope='Manual31-input normal two-deck subset: Play, held native Cue/bends, manual loops, PFL, eleven absolute mixer controls and repeated track-browse note pulses. No source script, mode, automatic identity/audio, motion, encoder-load or feedback claim.',
        gaps=[ref['review']])
    for deck,values in [('a',[20,13,1,8,15,14,22,17]),('b',[55,48,36,43,50,49,29,24])]:
        for action,n in zip(['play','cuePreview','loopIn','loopOut','reloop','pitchBendDown','pitchBendUp','cue'],values):add(p,action,0,n,deck=deck)
    for deck,values in [('a',[72,69,70,71,67]),('b',[75,76,74,73,66])]:
        for action,n in zip(['gain','high','mid','low','level'],values):add(p,action,0,n,'control',deck=deck)
    add(p,'crossfader',0,65,'control')
    for action,notes in [('browseNext',[82,80]),('browsePrevious',[83,81])]:
        for n in notes:add(p,action,0,n);p['inputs'][-1]['pulse']=True
    return [p]
